import {
  HubConnection,
  HubConnectionBuilder,
  HubConnectionState,
  LogLevel,
} from '@microsoft/signalr';

export interface SignalRConfig {
  hubUrl: string;
  /** Bağlantı öncesi çağrılır; güncel token döndürür */
  getAccessToken?: () => string | null;
  onReconnecting?: (error?: Error) => void;
  onReconnected?: (connectionId?: string) => void;
  onClose?: (error?: Error) => void;
}

/**
 * Yeni bir SignalR HubConnection oluşturur.
 * Otomatik reconnect ve token desteğiyle gelir.
 */
export function createHubConnection(config: SignalRConfig): HubConnection {
  const builder = new HubConnectionBuilder()
    .withUrl(config.hubUrl, {
      accessTokenFactory: config.getAccessToken
        ? () => config.getAccessToken!() ?? ''
        : undefined,
    })
    .withAutomaticReconnect()
    .configureLogging(
      import.meta.env.DEV ? LogLevel.Information : LogLevel.Warning,
    );

  const connection = builder.build();

  if (config.onReconnecting) connection.onreconnecting(config.onReconnecting);
  if (config.onReconnected) connection.onreconnected(config.onReconnected);
  if (config.onClose) connection.onclose(config.onClose);

  return connection;
}

export async function startConnection(connection: HubConnection): Promise<void> {
  if (connection.state === HubConnectionState.Disconnected) {
    await connection.start();
  }
}

export async function stopConnection(connection: HubConnection): Promise<void> {
  if (connection.state !== HubConnectionState.Disconnected) {
    await connection.stop();
  }
}

export { HubConnectionState };

import { createContext, useContext } from 'react';
import type { HubConnection } from '@microsoft/signalr';

export interface MessageHubContextValue {
  connection: HubConnection | null;
  isConnected: boolean;
  connectionId: string | null;
}

export const MessageHubContext = createContext<MessageHubContextValue>({
  connection: null,
  isConnected: false,
  connectionId: null,
});

export function useMessageHubContext() {
  return useContext(MessageHubContext);
}

import { useEffect, useRef, useState } from 'react';
import { HubConnectionState } from '@microsoft/signalr';
import { MessageHubContext } from './MessageHubContext';
import { createHubConnection, startConnection, stopConnection } from '@/lib/signalr';

interface MessageHubProviderProps {
  children: React.ReactNode;
  /** Hub URL — örn. import.meta.env.VITE_HUB_URL */
  hubUrl: string;
  /** Opsiyonel: güncel access token döndüren fonksiyon */
  getAccessToken?: () => string | null;
  /** false ise bağlantı başlatılmaz (kullanıcı giriş yapmamış vb.) */
  enabled?: boolean;
}

export function MessageHubProvider({
  children,
  hubUrl,
  getAccessToken,
  enabled = true,
}: MessageHubProviderProps) {
  const connectionRef = useRef(
    createHubConnection({ hubUrl, getAccessToken }),
  );
  const [isConnected, setIsConnected] = useState(false);
  const [connectionId, setConnectionId] = useState<string | null>(null);

  useEffect(() => {
    if (!enabled) return;

    const conn = connectionRef.current;

    conn.onreconnected((id) => {
      setIsConnected(true);
      setConnectionId(id ?? null);
    });

    conn.onreconnecting(() => {
      setIsConnected(false);
    });

    conn.onclose(() => {
      setIsConnected(false);
      setConnectionId(null);
    });

    startConnection(conn).then(() => {
      setIsConnected(conn.state === HubConnectionState.Connected);
      setConnectionId(conn.connectionId);
    });

    return () => {
      stopConnection(conn);
    };
  }, [enabled, hubUrl]);

  return (
    <MessageHubContext.Provider
      value={{ connection: connectionRef.current, isConnected, connectionId }}
    >
      {children}
    </MessageHubContext.Provider>
  );
}

import { useEffect, useCallback } from 'react';
import { useMessageHubContext } from '@/contexts/messageHub/MessageHubContext';

/**
 * SignalR hub'ına event listener bağlar.
 *
 * @example
 * useSignalR('ReceiveNotification', (data) => {
 *   console.log('Yeni bildirim:', data);
 * });
 */
export function useSignalR<T = unknown>(
  eventName: string,
  handler: (data: T) => void,
) {
  const { connection } = useMessageHubContext();

  const stableHandler = useCallback(handler, []);

  useEffect(() => {
    if (!connection) return;

    connection.on(eventName, stableHandler);

    return () => {
      connection.off(eventName, stableHandler);
    };
  }, [connection, eventName, stableHandler]);
}

import { useMessageHubContext } from '@/contexts/messageHub/MessageHubContext';

/**
 * Hub bağlantı durumunu ve invoke metodunu döner.
 *
 * @example
 * const { isConnected, invoke } = useMessageHub();
 * await invoke('SendMessage', { text: 'Merhaba' });
 */
export function useMessageHub() {
  const { connection, isConnected, connectionId } = useMessageHubContext();

  const invoke = async <T = void>(methodName: string, ...args: unknown[]): Promise<T> => {
    if (!connection) throw new Error('SignalR bağlantısı mevcut değil.');
    return connection.invoke<T>(methodName, ...args);
  };

  return { isConnected, connectionId, invoke };
}
